create or replace function refresh_kpis(p_organization_id uuid)returns integer language plpgsql security definer set search_path=public as $$declare n integer:=0;added integer:=0;src timestamptz;begin select completed_at into src from sync_batches where organization_id=p_organization_id and status='completed'order by completed_at desc limit 1;
insert into kpi_results(organization_id,kpi_definition_id,period_start,period_end,production_date,numerator,value,status,data_quality_status,source_refresh_at)select p_organization_id,d.id,date_trunc('day',now()),now(),current_date,x.value,x.value,'NO_TARGET',case when src is null then'NO_DATA'when src<now()-interval'24 hours'then'STALE_DATA'else'VALID'end,src from kpi_definitions d join lateral(values('TOTAL_BACKLOG',(select coalesce(sum(remaining_units),0)from v_production_planning where organization_id=p_organization_id)),('BACKLOG_ORDERS',(select count(distinct order_no)from v_production_planning where organization_id=p_organization_id)),('WIP',(select coalesce(sum(remaining_units),0)from v_production_planning where organization_id=p_organization_id)),('AGED_ORDERS',(select count(distinct order_no)from v_production_planning where organization_id=p_organization_id and age_days>=7)),('CURRENT_STOCK',(select coalesce(sum(production_units),0)from v_current_stock where organization_id=p_organization_id)),('UP_BACKLOG',(select coalesce(sum(remaining_units),0)from v_production_planning where organization_id=p_organization_id and line='UP')))x(code,value)on x.code=d.code where d.organization_id=p_organization_id and d.is_active;get diagnostics n=row_count;
insert into kpi_results(organization_id,kpi_definition_id,period_start,period_end,production_date,production_area_id,numerator,value,status,data_quality_status,source_refresh_at) select p_organization_id,d.id,date_trunc('day',now()),now(),current_date,a.id,sum(p.remaining_units),sum(p.remaining_units),'NO_TARGET',case when src is null then'NO_DATA'when src<now()-interval'24 hours'then'STALE_DATA'else'VALID'end,src from v_production_planning p join production_areas a on a.organization_id=p.organization_id and a.code=p.line join kpi_definitions d on d.organization_id=p.organization_id and d.code='WORKBANK_BY_DEPARTMENT' where p.organization_id=p_organization_id group by d.id,a.id;get diagnostics added=row_count;n=n+added;insert into kpi_results(organization_id,kpi_definition_id,period_start,period_end,production_date,production_area_id,numerator,denominator,value,status,data_quality_status,source_refresh_at)select p_organization_id,d.id,date_trunc('day',now()),now(),current_date,a.id,case when d.code='CAPACITY_LOAD'then l.demand_units else case when d.code='WORKBANK_BY_DEPARTMENT'then l.demand_units else l.daily_capacity end end,case when d.code='CAPACITY_LOAD'then l.daily_capacity end,case d.code when'AVAILABLE_CAPACITY'then l.daily_capacity when'CAPACITY_LOAD'then l.load_percent when'CAPACITY_GAP'then l.capacity_gap when'WORKBANK_BY_DEPARTMENT'then l.demand_units end,'NO_TARGET',case when src is null then'NO_DATA'when src<now()-interval'24 hours'then'STALE_DATA'else'VALID'end,src from v_capacity_load l join production_areas a on a.organization_id=l.organization_id and a.code=l.area_code join kpi_definitions d on d.organization_id=l.organization_id and d.code in('AVAILABLE_CAPACITY','CAPACITY_LOAD','CAPACITY_GAP')where l.organization_id=p_organization_id;get diagnostics added=row_count;n=n+added;return n;end$$;
revoke all on function refresh_kpis(uuid)from public,anon,authenticated;grant execute on function refresh_kpis(uuid)to service_role;
create or replace view v_kpi_dashboard with(security_invoker=true)as select d.id definition_id,d.organization_id,d.code,d.name,d.category,d.unit,d.data_readiness_status,d.dashboard_priority,r.value,r.numerator,r.denominator,r.status,r.data_quality_status,r.production_area_id,a.code area_code,r.source_refresh_at,r.calculated_at from kpi_definitions d left join lateral(select*from kpi_results x where x.kpi_definition_id=d.id order by calculated_at desc limit 1)r on true left join production_areas a on a.id=r.production_area_id;revoke all on v_kpi_dashboard from anon,authenticated;grant select on v_kpi_dashboard to service_role;
